Here's a C++ program that tokenizes a string using the `std::istringstream` class from the C++ Standard Library:

```cpp
#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::string input = "This is an example string.";
    std::istringstream iss(input);
    std::string token;

    std::cout << "Tokens in the string: " << std::endl;
    while (iss >> token) {
        std::cout << token << std::endl;
    }

    return 0;
}
```

This program will output:
```
